CREATE OR REPLACE FUNCTION funy_private.normalize_live_direct() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog,public AS $$ BEGIN IF NEW.location_type='direct' THEN NEW.created_at=now(); NEW.expires_at=(date_trunc('day',now() AT TIME ZONE 'Asia/Seoul')+interval '1 day') AT TIME ZONE 'Asia/Seoul'; NEW.shop_name=trim(NEW.shop_name); NEW.shop_id='LIVE-PIN:'||NEW.country_code||':'||round(NEW.latitude::numeric,5)::text||':'||round(NEW.longitude::numeric,5)::text; NEW.is_hidden=false; NEW.hidden_at=NULL; NEW.hidden_reason=NULL; END IF; RETURN NEW; END $$; ALTER TRIGGER trg_normalize_live_direct ON public.live_reports RENAME TO trg_a_normalize_live_direct;
